import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";

// Layouts
import StudentLayout from "./pages/StudentLayout"; // تأكد من استيراد الـ Layout الجديد

// Public
import Landing      from "./pages/Landing";
import Login        from "./pages/Login";
import Register     from "./pages/Register";
import NotFound     from "./pages/NotFound";

// Student
import StudentDashboard    from "./pages/StudentDashboard";
import StudentSearch       from "./pages/StudentSearch";
import StudentApplications from "./pages/StudentApplications";
import StudentProfile      from "./pages/StudentProfile";

// ... بقية الاستيرادات للـ Company والـ Admin ...

export default function App() {
  return (
    <BrowserRouter future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
      <Routes>

        {/* ── Public ── */}
        <Route path="/"         element={<Landing />} />
        <Route path="/login"    element={<Login />} />
        <Route path="/register" element={<Register />} />

        {/* ── Student (المسارات المتداخلة) ── */}
        <Route path="/student" element={<StudentLayout />}>
          {/* هذا المسار يجعل الطالب يتوجه تلقائياً للـ Dashboard عند دخوله /student */}
          <Route index element={<Navigate to="dashboard" replace />} />
          
          <Route path="dashboard"    element={<StudentDashboard />} />
          <Route path="search"       element={<StudentSearch />} />
          <Route path="applications" element={<StudentApplications />} />
          <Route path="profile"      element={<StudentProfile />} />
        </Route>

        {/* يمكنك فعل نفس الشيء للـ Company والـ Admin لاحقاً */}
        <Route path="/company/dashboard"  element={<CompanyDashboard/>} />
        {/* ... إلخ ... */}

        {/* ── 404 ── */}
        <Route path="*" element={<NotFound />} />

      </Routes>
    </BrowserRouter>
  );
}
